def _q(b: int, n: int, d: str, p: str, correct: str, wrongs: list[str], e: str, h: str = '', fig=None) -> dict:
    return make_q(f'MT9-B{b:02d}-{n:03d}', d, p, correct, wrongs, e, S, h, fig)


